import {BeakerIcon} from '@primer/octicons-react'
import type {Sku} from '@github-ui/licensing-common/copilot-types'
import {SummaryCard} from '@github-ui/licensing-common/components/SummaryCard'
import {SummaryCardTwoSectionBody} from '@github-ui/licensing-common/components/SummaryCardTwoSectionBody'
import {UsageSummary} from '@github-ui/licensing-common/components/UsageSummary'
import {LicenseCount} from '@github-ui/licensing-common/components/LicenseCount'
import {PaymentSummary} from '@github-ui/licensing-common/components/PaymentSummary'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {ManageButton} from './ManageButton'
import {EnableCTA} from './EnableCTA'

export interface SummaryProps {
  isCodeQualityEnabled: boolean
  configureButtonPath: string
  sku: Sku | null
  billingTermEndDate: string | null
  totalCost: number
}

function formatCurrency(amount: number): string {
  return `$${amount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`
}

export function Summary({isCodeQualityEnabled, configureButtonPath, sku, billingTermEndDate, totalCost}: SummaryProps) {
  const {isStafftools} = useNavigation()

  return (
    <SummaryCard
      headerIconComponent={BeakerIcon}
      title="Code Quality"
      headerActions={isCodeQualityEnabled ? <ManageButton configureButtonPath={configureButtonPath} /> : undefined}
    >
      {isCodeQualityEnabled ? (
        <SummaryCardTwoSectionBody
          primarySection={
            <UsageSummary title="Consumed licenses">
              <LicenseCount consumed={sku?.consumedLicenses ?? 0} description="Code Quality licenses" />
            </UsageSummary>
          }
          secondarySection={
            <PaymentSummary
              title="Estimated monthly payment"
              currentPayment={formatCurrency(totalCost)}
              description={`Amount based on ${(sku?.billableLicenses ?? 0).toLocaleString()} billable licenses${billingTermEndDate ? `, due by ${billingTermEndDate}` : ''}.`}
              productName="Code Quality"
            />
          }
          testId="code-quality-usage-payment-summary"
        />
      ) : isStafftools ? (
        <div className="Box-body" data-testid="stafftools-code-quality-disabled">
          Code Quality is not enabled on this enterprise.
        </div>
      ) : (
        <EnableCTA />
      )}
    </SummaryCard>
  )
}
