import {NavigationContextProvider} from '@github-ui/licensing-common/contexts/NavigationContext'
import {Summary, type SummaryProps} from './Summary'

export interface OverviewProps {
  enterpriseContactUrl?: string
  codeQuality: SummaryProps
  isStafftools?: boolean
  slug: string
}

export function Overview({codeQuality, enterpriseContactUrl = '', isStafftools = false, slug}: OverviewProps) {
  const hasUsage = (codeQuality.sku?.consumedLicenses ?? 0) !== 0 || (codeQuality.sku?.billableLicenses ?? 0) !== 0

  if (codeQuality.isCodeQualityEnabled && !hasUsage) {
    return null
  }

  return (
    <NavigationContextProvider enterpriseContactUrl={enterpriseContactUrl} isStafftools={isStafftools} slug={slug}>
      <div className="tmp-mb-4" data-testid="licensing-code-quality-overview">
        <Summary {...codeQuality} />
      </div>
    </NavigationContextProvider>
  )
}
